INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('witch-hunter-robin','Witch Hunter ROBIN','Witch Hunter ROBIN',2002,7.2,'Summer 2002','TV','Finished','https://media.kitsu.app/anime/poster_images/4/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/7-hjjlCe3yO7lO.jpg','#8b5cf6','Witches are individuals with special powers like ESP, telekinesis, mind control, etc. (not the typical hogwart and newt potions). Robin, a 15-year-old craft user, arrives from Italy to Japan to work for an organization named STN Japan Division (STN-J) as a replacement for one of STN-J''s witch hunters who was recently killed. Unlike other divisions of STN, STN-J tries to capture the witches alive in order to learn why and how they became witches in the first place. (Source: ANN)',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":4,"anilist":7,"mal":7}',7,'anilist',26,datetime('now'),'witch hunter robin witch hunter robin tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('my-new-boss-is-goofy','My New Boss is Goofy','新しい上司はど天然',2023,7.9,'Fall 2023','TV','Finished','https://media.kitsu.app/anime/47480/poster_image/medium-93805cc161be97ba151da48fafedf3b2.jpeg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/165070-ucfoOkYvLKlH.jpg','#24d3ee','The story of Atarashii Joushi wa Dotennen follows Kentarou Momose, a 26 year old office worker who ends up leaving his previous job because of terrible "power harassment" from his previous boss. At first Momose is stressed that his new boss, Yuusei Shirosaki, may give him a similarly poor treatment, but it turns out that Shirosaki is a bit of a natural airhead despite his serious and severe-looking demeanor. (Source: Crunchyroll)',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":47480,"anilist":165070,"mal":55310}',55310,'mal',12,datetime('now'),'my new boss is goofy 新しい上司はと 天然 tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
INSERT INTO anime (id,title,native,year,rating,season,kind,status,art,key_art,accent,synopsis,rank,alt_seasons,sched_day,sched_day_label,sched_date,sched_time,sched_season,source_ids,skip_key_id,skip_key_space,episode_total,added_at,search_text,catalogue_synced_at) VALUES ('hortensia-saga','Hortensia SAGA','オルタンシア・サーガ',2021,5.9,'Winter 2021','TV','Finished','https://media.kitsu.app/anime/poster_images/43568/medium.jpg','https://s4.anilist.co/file/anilistcdn/media/anime/banner/114301-vPL85yxiKDTH.jpg','#2f7bff','When the duke of Hortensia murdered the king, he unleashed a wave of chaos that spilled the blood of many. Brazenly building his kingdom on the ashes of the old one, his violent rule has left many orphans in its wake. But now, the king’s heir has come of age. Living in secret as a man, she’s remained safe, and the time has come to gather allies to take back what is her’s—both country and throne! (Soure: Funimation)',NULL,'[]',NULL,NULL,NULL,NULL,NULL,'{"kitsu":43568,"anilist":114301,"mal":40961}',40961,'mal',12,datetime('now'),'hortensia saga オルタンシア サーカ tv finished',CAST(strftime('%s','now') AS INTEGER) * 1000) ON CONFLICT(id) DO UPDATE SET title=excluded.title,native=excluded.native,year=excluded.year,rating=excluded.rating,season=excluded.season,kind=excluded.kind,status=excluded.status,art=excluded.art,key_art=excluded.key_art,accent=excluded.accent,synopsis=excluded.synopsis,rank=excluded.rank,alt_seasons=excluded.alt_seasons,sched_day=excluded.sched_day,sched_day_label=excluded.sched_day_label,sched_date=excluded.sched_date,sched_time=excluded.sched_time,sched_season=excluded.sched_season,source_ids=excluded.source_ids,skip_key_id=excluded.skip_key_id,skip_key_space=excluded.skip_key_space,episode_total=excluded.episode_total,search_text=excluded.search_text,catalogue_synced_at=excluded.catalogue_synced_at;
