INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#1','macross-delta',1,'Prologue on the Battlefield','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185749/original.jpg','Looking to escape the confines of an arranged marriage on her home planet, Freyja Wion stows away on a cargo ship, hoping to follow her dreams and audition for the Walkure Tactical Music Unit. She''s discovered by Hayate Immelmann, a young dock worker and drifter with no particular dreams of his own. After an outbreak of the deadly Var Syndrome strikes, the Walkure Unit appears on the scene, and the power of Freyja''s music is awakened.','[]','2016-04-03','185749');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#2','macross-delta',2,'Audition with Death','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185750/original.jpg','In the aftermath of the Var Syndrome Outbreak on Al Shahal, new opportunities present themselves for Freyja and Hayate. They make their way to Planet Ragna where Freyja auditions to be the newest member of Walkure, and Hayate receives an intriguing offer from Delta Flight.','[]','2016-04-10','185750');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#3','macross-delta',3,'A Stormy Dogfight','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185751/original.jpg','Mirage is assigned to train Hayate, who has become the newest recruit for Delta Flight. Freyja continues her Walküre training. As Hayate and Freyja both struggle through their respective initiations, they soon discover that they are stronger together than they are apart.','[]','2016-04-17','185751');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#4','macross-delta',4,'A Shocking Debut Show','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185752/original.jpg','At a concert on the nearby planet Randall, Freyja makes her official debut as the newest member of Walküre. The Aerial Knights of Windermere interrupt the festivities and finally make their true intentions known.','[]','2016-04-24','185752');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#5','macross-delta',5,'Moonlight Dancing','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185753/original.jpg','Following the Windermere Kingdom''s declaration of war on the New United Government, Delta Flight and Walküre are given new orders to defend Ragna from upcoming attacks. When rumors of Freyja being a Windermerian spy surface, she and Hayate take a joyride in his Siegfried unit to clear their heads.','[]','2016-05-01','185753');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#6','macross-delta',6,'Decision Overload','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185754/original.jpg','Hayate and Freyja continue to be put through their paces as the war with the Windermere Kingdom begins. Mikumo challenges Freyja to find what she''s fighting for, while Messer gives harsh criticism to both Mirage and Hayate hoping to strengthen their resolve for the war to come. When the Aerial Knights attack, Hayate is put in an impossible situation and is forced to make a decision that will change his life forever.','[]','2016-05-08','185754');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#7','macross-delta',7,'Behind Enemy Lines','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185755/original.jpg','Walküre and Delta Flight infiltrate the planet Voldor, which has been occupied by the Aerial Knights of the Windermere Kingdom. The source behind the increased Var Syndrome Outbreaks is revealed.','[]','2016-05-15','185755');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#8','macross-delta',8,'Escape Resonance','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185756/original.jpg','Hayate, Freyja, and Mirage have been captured by the Aerial Knights, and it''s up to the rest of Walküre and Delta Flight to stage a daring rescue. Freyja and Hayate discover what happens when they are truly in sync. Meanwhile, Messer must deal with his worsening condition.','[]','2016-05-22','185756');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#9','macross-delta',9,'Uncontrolled on the Edge','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185757/original.jpg','The extent of Messer''s condition is finally revealed. The Aerial Knights make a move on Ragna while most of the Elysion squadrons are out on patrol, and a weakened Messer must fight through his illness to protect the others. Meanwhile, rumors begin to circulate about a blossoming romance between Hayate and Mirage.','[]','2016-05-29','185757');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#10','macross-delta',10,'Axia Flash','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185758/original.jpg','At the Jellyfish Festival on Ragna, Messer says goodbye, as he reveals that he has been reassigned as a training instructor due to his worsening condition. Meanwhile, the Windermearans have developed a new system to amplify Prince Heinz'' wind song. The Aerial Knights launch a surprise attack and Var Outbreak on Al-Shahal to test the new system. The Delta team must protect Al-Shahal from the Knights'' attack even though they are one man short...','[]','2016-06-05','185758');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#11','macross-delta',11,'Jellyfish Reminiscence','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185759/original.jpg','Delta Flight and Walküre take time out to mourn the loss of one of their own. The grand plan of the Windermereans is revealed and set into motion.','[]','2016-06-12','185759');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#12','macross-delta',12,'King of the Wind','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185760/original.jpg','The Windermerans and the Sigur Berrentzs go on the offensive and launch an attack on NUNS forces. The Macross Elysion is ordered to leave its post on Ragna and to meet the Windermerean threat in space. Mirage receives surprising news from Major Arad about her status in Delta Flight.','[]','2016-06-19','185760');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#13','macross-delta',13,'Passionate Diving','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185761/original.jpg','The Windermerean attack continues and the fate of the inhabitants of Planet Ragna hangs in the balance.','[]','2016-06-26','185761');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#14','macross-delta',14,'Embracing Adrift','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185762/original.jpg','In the aftermath of the the battle for Ragna, Ragnan evacuees adjust to life in space. When an airlock explodes, the entire team must work together to find a solution.','[]','2016-07-03','185762');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#15','macross-delta',15,'Parting Resolution','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185763/original.jpg','Prince Heinz is crowned the new King of Windermere. Roid reveals King Grammier''s grand plan to expand the Windermere Kingdom across the galaxy.','[]','2016-07-10','185763');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#16','macross-delta',16,'Hesitating Birthday','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185764/original.jpg','Makina and the rest of the gang decide to throw Freyja a surprise party for her 15th birthday. Hayate has trouble finding a birthday gift and enlists Mirage for help.','[]','2016-07-17','185764');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#17','macross-delta',17,'Scatter on Stage','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185765/original.jpg','Delta Flight and Walkure devise a plan to interrupt the Windermeran Mind Control in the Brisingr Cluster, using a special Walkure concert as a distraction. Hayate learns the shocking truth about his father.','[]','2016-07-24','185765');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#18','macross-delta',18,'Sense Emergence','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185766/original.jpg','Delta Flight and Walküre infiltrate Voldor once again, this time to test the Protoculture ruins'' reaction to Walküre''s live music. Freyja and Hayate encounter the enemy face to face, and are surprised at what they find. Mikumo tests her limits to potentially disastrous results.','[]','2016-07-31','185766');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#19','macross-delta',19,'Eternal Songs','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185767/original.jpg','While Mikumo and Hayate are both recovering from the infiltration on Voldor, Berger Stone from the Epsilon Group meets with Delta Flight and Walküre and reveals how the power of song and the Var Syndrome are related.','[]','2016-08-07','185767');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#20','macross-delta',20,'Impulse Experiment','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185768/original.jpg','Hayate and Freyja''s fold resonance is put to the test. When both become discouraged, Mirage steps in to straighten things out. Keith begins to suspect Roid''s true intentions. Makina, Reina and Kaname search for answers about Mikumo.','[]','2016-08-14','185768');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#21','macross-delta',21,'Yearning Secret','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185769/original.jpg','Keith discovers that the amplified Windsong is beginning to take its toll on King Heinz. As Kaname, Makina, and Reina await their fate, they reminisce about the early days of Walküre.','[]','2016-08-21','185769');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#22','macross-delta',22,'Extreme Brave','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185770/original.jpg','Xaos goes on the offensive and pushes on with their plan to invade Windermere. Freyja and Hayate return to active duty, under special orders from Major Arad, leaving Mirage responsible for the two of them. Keith and Heinz clear the air. Cassim rides the wind.','[]','2016-08-28','185770');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#23','macross-delta',23,'Scarred Requiem','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185771/original.jpg','Delta Flight and Walküre finally land on Windermere, on a mission to destroy the Protoculture system with a Tactical Live show. Their plans go awry when the Aerial Knights discover their presence and move to intercept them. Meanwhile, Roid has bigger things planned for Mikumo.','[]','2016-09-04','185771');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#24','macross-delta',24,'Fatal Judgment','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185772/original.jpg','Hayate, Freyja, and Mirage have been captured and are put on trial by order of King Heinz. Meanwhile, Commander Arad and the rest of Walküre plan their rescue.','[]','2016-09-11','185772');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#25','macross-delta',25,'Star Singer','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185773/original.jpg','Windermere''s endgame is set into motion, as the ultimate plan for the Singer of the Stars is revealed. Xaos gets recalled to Ragna to prepare for the final showdown against Windermere.','[]','2016-09-18','185773');
INSERT OR REPLACE INTO episode (id,anime_id,n,title,runtime,runtime_seconds,thumb,synopsis,markers,airdate,external_id) VALUES ('macross-delta#26','macross-delta',26,'Eternal Walküre','23:00',1380,'https://media.kitsu.app/episodes/thumbnails/185774/original.jpg','Roid attempts to control the Singer of the Stars as the final showdown against the Aerial Knights takes place at the Protoculture Ruins on Ragna.','[]','2016-09-25','185774');

